import{_ as i,o as t,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"快速启动设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/quick-launch.md","filePath":"zh-CN/user-guide/settings/quick-launch.md","lastUpdated":1788171291000}'),e={name:"zh-CN/user-guide/settings/quick-launch.md"};function o(n,l,s,u,h,d){return t(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="快速启动设置" tabindex="-1">快速启动设置 <a class="header-anchor" href="#快速启动设置" aria-label="Permalink to &quot;快速启动设置&quot;">​</a></h1><p>快速启动是快速搜索窗口在搜索框为空时显示的启动面板。它会组合手动管理的项目，以及收藏夹、历史记录等已选中的动态数据源。</p><h2 id="_1-总开关" tabindex="-1">1. 总开关 <a class="header-anchor" href="#_1-总开关" aria-label="Permalink to &quot;1. 总开关&quot;">​</a></h2><ul><li><strong>启用快速启动面板</strong>：启用该面板。只有在快速搜索窗口的搜索框为空，且至少有一个数据源存在可用数据时，面板才会显示。</li><li>关闭后，面板不会加载任何数据源。</li><li>面板高度会根据项目数量最多的数据源计算，同时不会超过快速搜索窗口结果区域的最大高度。</li></ul><h2 id="_2-手动快速启动项目" tabindex="-1">2. 手动快速启动项目 <a class="header-anchor" href="#_2-手动快速启动项目" aria-label="Permalink to &quot;2. 手动快速启动项目&quot;">​</a></h2><p>打开<strong>设置 → 快速启动 → 快速启动</strong>，即可管理自己的项目：</p><ul><li>可以添加文件、文件夹、网址或 Windows Shell 路径，检查目标时支持展开环境变量。</li><li>显示名称可以留空，留空时 Lertaro 会根据目标自动生成名称。</li><li>文件和文件夹浏览按钮支持一次选择多个项目，每个有效且不重复的目标都会作为独立项目添加。</li><li>使用拖拽手柄调整顺序。点击编辑后，当前行会变成带有保存和取消按钮的就地编辑器；删除按钮用于移除项目。</li><li>对于手动项目，将鼠标悬停在卡片上并点击省略号按钮即可打开菜单，然后选择<strong>编辑</strong>或<strong>删除</strong>；<strong>编辑</strong>会打开项目编辑对话框。</li><li>列表有内容时，可以使用列表标题右侧的<strong>清空列表</strong>按钮一次移除所有手动项目；列表为空时该按钮会隐藏。</li><li>当前不可用的目标会从面板中隐藏，目标恢复可用后会自动重新出现。</li></ul><h2 id="_3-数据源" tabindex="-1">3. 数据源 <a class="header-anchor" href="#_3-数据源" aria-label="Permalink to &quot;3. 数据源&quot;">​</a></h2><p>打开<strong>设置 → 快速启动 → 数据源</strong>，即可选择动态数据源：</p><ul><li>数据源来自已安装的快速面板标签页提供程序，因此快速启动可以直接复用收藏夹、历史记录、Windows 历史记录、上次目录、最近文件以及后续插件数据源，不需要维护第二份数据。</li><li>数据源提供程序存在时默认启用，用户设置中只保存明确关闭的数据源。</li><li>只有已启用且当前能返回数据的数据源才会创建面板标签页，没有数据的源会隐藏。</li><li>可以通过数据源旁的拖拽手柄调整面板标签页顺序，该顺序会随快速启动设置保存。</li><li>当所有手动项目和动态数据源都没有数据时，快速启动面板会隐藏。</li></ul><h2 id="_4-面板交互" tabindex="-1">4. 面板交互 <a class="header-anchor" href="#_4-面板交互" aria-label="Permalink to &quot;4. 面板交互&quot;">​</a></h2><ul><li>面板列数会根据搜索栏宽度自适应。</li><li>只有一个数据源时，底部数据源指示器会隐藏。</li><li>有多个数据源时，底部会为每个数据源显示一个圆点。选中的圆点为蓝色，未选中的圆点为灰色；鼠标悬停时圆点会展开显示数据源名称。</li><li>在面板上按住 <strong>Shift</strong> 滚动鼠标滚轮可以循环切换数据源，切换后的数据源会短暂播放同样的展开动画。</li><li>配置的<strong>选中下一项</strong>和<strong>选中上一项</strong>快捷键（默认是 <strong>Ctrl+N</strong> 和 <strong>Ctrl+P</strong>）在面板显示时也可以循环切换数据源，到达末尾后会回到第一个数据源，反向切换时同理。</li><li>右键单击任意数据源中的项目，可以打开该项目的标准动作菜单。</li><li>当面板中的项目超出可见高度时，可以在项目区域使用鼠标滚轮进行垂直滚动；鼠标悬停在项目上不会阻止滚动。</li><li>开始输入搜索内容后，面板会隐藏。</li></ul>',12)])])}const _=i(e,[["render",o]]);export{g as __pageData,_ as default};
